export type RateCircuitBreakerState = "closed" | "open" | "half-open";

export interface RateCircuitBreakerOptions {
  /** Number of failures in the sliding window that opens the circuit. */
  failureThreshold: number;
  /** Length of the failure window and, separately, the open-state cooldown. */
  windowMs: number;
  cooldownMs: number;
  /** Injectable monotonic-ish clock. Defaults to Date.now. */
  now?: () => number;
}

export interface RateCircuitBreakerDecision {
  allowed: boolean;
  state: RateCircuitBreakerState;
  reason?: "closed" | "cooldown" | "probe-in-flight";
}

/**
 * A deterministic, opt-in circuit breaker for exceptional call rates.
 *
 * The caller must check `allowRequest()` before performing any externally
 * visible effect. A request rejected while open has no effect on the circuit;
 * in particular, it is not counted as a probe failure.
 */
export class RateCircuitBreaker {
  private readonly failureThreshold: number;
  private readonly windowMs: number;
  private readonly cooldownMs: number;
  private readonly clock: () => number;
  private failures: number[] = [];
  private currentState: RateCircuitBreakerState = "closed";
  private openedAt = 0;
  private probeInFlight = false;

  public constructor(options: RateCircuitBreakerOptions) {
    if (!Number.isFinite(options.failureThreshold) || options.failureThreshold <= 0) {
      throw new RangeError("failureThreshold must be a positive finite number");
    }
    if (!Number.isFinite(options.windowMs) || options.windowMs <= 0) {
      throw new RangeError("windowMs must be a positive finite number");
    }
    if (!Number.isFinite(options.cooldownMs) || options.cooldownMs < 0) {
      throw new RangeError("cooldownMs must be a non-negative finite number");
    }
    this.failureThreshold = options.failureThreshold;
    this.windowMs = options.windowMs;
    this.cooldownMs = options.cooldownMs;
    this.clock = options.now ?? Date.now;
  }

  public get state(): RateCircuitBreakerState {
    return this.currentState;
  }

  public get failureCount(): number {
    this.pruneFailures(this.clock());
    return this.failures.length;
  }

  /**
   * Returns true only when the caller may perform the requested operation.
   * In half-open state this reserves the single probe slot.
   */
  public allowRequest(): boolean {
    return this.acquire().allowed;
  }

  /** Alias suitable for policy middleware. */
  public canRequest(): boolean {
    return this.allowRequest();
  }

  /** Returns a decision without requiring callers to infer the current state. */
  public acquire(): RateCircuitBreakerDecision {
    const now = this.clock();
    this.pruneFailures(now);

    if (this.currentState === "open") {
      if (now - this.openedAt < this.cooldownMs) {
        return { allowed: false, state: "open", reason: "cooldown" };
      }
      this.currentState = "half-open";
      this.probeInFlight = false;
    }

    if (this.currentState === "half-open") {
      if (this.probeInFlight) {
        return { allowed: false, state: "half-open", reason: "probe-in-flight" };
      }
      this.probeInFlight = true;
      return { allowed: true, state: "half-open" };
    }

    return { allowed: true, state: "closed", reason: "closed" };
  }

  /** Records a successful permitted operation. */
  public recordSuccess(): void {
    if (this.currentState === "half-open") {
      this.currentState = "closed";
      this.probeInFlight = false;
      this.failures = [];
    }
  }

  /** Records a failed permitted operation. */
  public recordFailure(): void {
    const now = this.clock();
    this.pruneFailures(now);

    if (this.currentState === "half-open") {
      this.trip(now);
      return;
    }

    if (this.currentState === "open") {
      return;
    }

    this.failures.push(now);
    if (this.failures.length >= this.failureThreshold) {
      this.trip(now);
    }
  }

  /** Clears all accumulated state without affecting the clock. */
  public reset(): void {
    this.currentState = "closed";
    this.failures = [];
    this.probeInFlight = false;
    this.openedAt = 0;
  }

  private trip(now: number): void {
    this.currentState = "open";
    this.openedAt = now;
    this.probeInFlight = false;
    this.failures = [];
  }

  private pruneFailures(now: number): void {
    const cutoff = now - this.windowMs;
    while (this.failures.length > 0 && this.failures[0] <= cutoff) {
      this.failures.shift();
    }
  }
}

export default RateCircuitBreaker;

